begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public;
select plan(15);
select has_function('pcm','sso_reconciliar_cronograma_por_ator',array['uuid','uuid','uuid','uuid','integer','text'],'entrada de reconciliação com ator existe');
select ok(has_function_privilege('authenticated','pcm.sso_reconciliar_cronograma_por_ator(uuid,uuid,uuid,uuid,integer,text)','execute'),'autenticado pode solicitar reconciliação mediada');
select ok(not has_function_privilege('anon','pcm.sso_reconciliar_cronograma_por_ator(uuid,uuid,uuid,uuid,integer,text)','execute'),'anônimo não executa');
select ok(not has_function_privilege('service_role','pcm.sso_reconciliar_cronograma_por_ator(uuid,uuid,uuid,uuid,integer,text)','execute'),'service role não contorna sessão');
select ok(not has_function_privilege('authenticated','pcm.sso_reconciliar_cronograma_conferido(uuid,uuid,uuid,integer,text)','execute'),'entrada antiga não contorna ator esperado');
select ok(not has_function_privilege('authenticated','pcm.sso_reconciliar_cronograma_legado(uuid,uuid,uuid,integer,text)','execute'),'núcleo antigo não contorna conferência');
select ok(not has_table_privilege('authenticated','pcm.sso_reconciliacao_cronograma_gate','update'),'usuário não altera gate');
select ok(not has_table_privilege('authenticated','pcm.sso_reconciliacoes_cronograma','select'),'ledger não é acessível diretamente');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='pcm.sso_reconciliacoes_cronograma'::regclass),'ledger usa RLS FORCE');
select ok(not has_function_privilege('authenticated','pcm.sso_receber_matriz_cronograma(uuid,uuid,uuid,text,jsonb)','execute'),'escritor legado permanece revogado');
select has_function('pcm','sso_listar_cronogramas_legados',array['uuid','uuid','integer'],'listagem mediada existe');
select ok(has_function_privilege('authenticated','pcm.sso_listar_cronogramas_legados(uuid,uuid,integer)','execute'),'autenticado pode solicitar listagem');
select ok(not has_function_privilege('anon','pcm.sso_listar_cronogramas_legados(uuid,uuid,integer)','execute'),'anônimo não lista');
select ok(not has_function_privilege('service_role','pcm.sso_listar_cronogramas_legados(uuid,uuid,integer)','execute'),'service role não contorna sessão');
select ok(not has_table_privilege('authenticated','pcm.sso_listagem_cronograma_legado_gate','update'),'usuário não altera gate de leitura');
select * from finish();
rollback;
